<script setup>
import { ref, onMounted, computed } from 'vue'
import { api, bolivianos } from '../services/api'
const celulares = ref([]), ventas = ref([]), error = ref('')
onMounted(async () => { try { [celulares.value, ventas.value] = await Promise.all([api.listar('celulares'), api.listar('ventas')]) } catch(e) { error.value = e.message } })
const ingresos = computed(() => ventas.value.reduce((s,v) => s + Number(v.total || 0), 0))
const stock = computed(() => celulares.value.reduce((s,c) => s + Number(c.stock || 0), 0))
</script>
<template><div class="page-heading"><div><div class="eyebrow">RESUMEN GENERAL</div><h1>Dashboard</h1><p>Bienvenido al panel de control de CellStore.</p></div><span class="date-pill"><i class="bi bi-calendar3"></i> {{ new Date().toLocaleDateString('es-BO') }}</span></div>
 <div v-if="error" class="alert alert-danger">{{ error }}</div>
 <div class="row g-4 mb-4"><div class="col-md-6 col-xl-3" v-for="stat in [{label:'Modelos de celulares',value:celulares.length,icon:'bi-phone',tone:'blue'},{label:'Unidades en stock',value:stock,icon:'bi-box-seam',tone:'violet'},{label:'Ventas registradas',value:ventas.length,icon:'bi-bag-check',tone:'orange'},{label:'Ingresos totales',value:bolivianos(ingresos),icon:'bi-cash-stack',tone:'green'}]" :key="stat.label"><div class="stat-card"><div class="stat-icon" :class="stat.tone"><i class="bi" :class="stat.icon"></i></div><div class="stat-label">{{ stat.label }}</div><div class="stat-value">{{ stat.value }}</div></div></div></div>
 <div class="row g-4"><div class="col-lg-7"><div class="panel h-100"><div class="panel-title"><h3>Últimas ventas</h3><router-link to="/ventas">Ver todas <i class="bi bi-arrow-right"></i></router-link></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Cliente</th><th>Celular</th><th>Total</th></tr></thead><tbody><tr v-for="v in [...ventas].slice(-5).reverse()" :key="v.id"><td>{{ v.cliente }}</td><td>{{ v.producto }}</td><td class="fw-semibold">{{ bolivianos(v.total) }}</td></tr><tr v-if="!ventas.length"><td colspan="3" class="text-muted text-center">Sin ventas registradas</td></tr></tbody></table></div></div></div><div class="col-lg-5"><div class="panel h-100"><div class="panel-title"><h3>Accesos rápidos</h3></div><p class="text-muted">Administra tu tienda desde estas secciones.</p><router-link to="/celulares" class="quick-link"><i class="bi bi-plus-circle"></i><span>Gestionar celulares<small>Inventario y precios</small></span><i class="bi bi-chevron-right ms-auto"></i></router-link><router-link to="/ventas" class="quick-link"><i class="bi bi-receipt"></i><span>Registrar venta<small>Operaciones comerciales</small></span><i class="bi bi-chevron-right ms-auto"></i></router-link><router-link to="/reportes" class="quick-link"><i class="bi bi-graph-up-arrow"></i><span>Consultar reportes<small>Estadísticas e ingresos</small></span><i class="bi bi-chevron-right ms-auto"></i></router-link></div></div></div>
</template>
